# CS 이관 기록 (자동이체 알림)

결제운영팀이 개발로 넘긴 문의 묶음. 처리 내용은 CHANGELOG를 본다.

| 티켓 | 접수 | 문의 요약 | 건수 | 상태 |
|---|---|---|---|---|
| CS-2104 | 2025-01-09 | 해지한 계약의 출금 예정 알림이 계속 온다 | 12 | 완료(1.8.0) |
| CS-2188 | 2025-03-03 | 새벽 출금 계약의 알림이 출금 뒤 07:00에 온다 | 7 | 완료(1.8.2) |
| CS-2291 | 2025-04-11 | 같은 재출금 안내를 몇 분 간격으로 세 번 받음. "세 번 빠져나가는 거냐" 문의, 일부는 해지 요청. 08시 배치 실패분에 몰림 | 41 | 완료(1.9.0) |
| CS-2350 | 2025-06-23 | 알림 문구의 가맹점명이 잘림 | 3 | 보류(문구 정책) |
| CS-2477 | 2026-01-15 | 앱 구버전 고객이 알림을 못 받음(대문자 토큰) | 9 | 완료(2.0.0) |
| CS-2603 | 2026-07-30 | 13:47 같은 가맹점 시각 계약의 알림 미수신 | 18 | 완료(2.1.0) |
----
import { Autopay } from "../src/domain/autopay";
import { reminderKey } from "../src/domain/reminder";
import { maskDevice, normalizeDevice } from "../src/push/deviceToken";
import { renderMessage } from "../src/push/messageTemplates";
import { shortMerchant, won } from "../src/util/money";
import { eq, run, test } from "./harness";

const contract: Autopay = {
  id: "AP00007",
  memberId: "M1",
  merchant: "아주긴이름의프리미엄스트리밍서비스",
  amount: 1234567,
  billingDay: 5,
  billingTime: "09:30",
  active: true,
};

test("money and merchant names are formatted for one push line", () => {
  eq(won(0), "0원", "zero");
  eq(won(1234567), "1,234,567원", "thousands");
  eq(won(-5000), "-5,000원", "negative");
  eq(shortMerchant("든든손해보험"), "든든손해보험", "short name");
  eq(shortMerchant(contract.merchant), "아주긴이름의프리미엄스…", "long name");
});

test("reminder texts mention merchant, amount and withdrawal time", () => {
  eq(
    renderMessage("BILL_DUE", contract, "2026-11-05T09:30:00"),
    "[한빛페이] 아주긴이름의프리미엄스… 자동이체 1,234,567원이 11/5 09:30에 출금됩니다. 잔액을 확인해 주세요.",
    "bill due",
  );
  eq(
    renderMessage("RETRY", contract, "2026-11-05T11:30:12"),
    "[한빛페이] 아주긴이름의프리미엄스… 자동이체 1,234,567원 출금이 실패해 11/5 11:30에 다시 출금합니다.",
    "retry",
  );
});

test("reminder keys and device tokens are stable", () => {
  eq(reminderKey("BILL_DUE", "AP00007", "2026-11-05T09:30:00"), "rmd.AP00007.due.20261105", "due key");
  eq(reminderKey("RETRY", "AP00007", "2026-11-05T11:30:12"), "rmd.AP00007.retry.20261105", "retry key");
  eq(reminderKey("RETRY", "AP00007", "2026-11-05T11:36:12"), "rmd.AP00007.retry.20261105", "retry key later the same day (CS-2291)");
  eq(normalizeDevice("  IOS:AbCdEf123456 "), "ios:AbCdEf123456", "normalized");
  eq(maskDevice("and:Zz9988776655"), "and:Zz99…55", "masked");
  let threw = false;
  try {
    normalizeDevice("web:AbCdEf123456");
  } catch {
    threw = true;
  }
  eq(threw, true, "unknown platform rejected");
});

run();
----
import { addMinutes, fromEpochSeconds, LocalDateTime, toEpochSeconds } from "../time/localTime";
import { QuietHours } from "./quietHours";

/** pushq 는 5분 경계(분이 5의 배수, 초 00)가 아닌 예약 시각을 티켓만 주고 큐에 넣지 않는다. */
const PUSH_SLOT_SECONDS = 300;

/**
 * 알림 발송 시각 정책.
 * - 안내 대상 시각(출금·재출금)보다 lead 분 앞서 보낸다.
 * - 야간 방해 금지 구간에 걸리면 전날 저녁으로 당긴다.
 * - 푸시 예약 시각은 직전 5분 경계로 내린다(늦게 보내지 않는다).
 */
export class SendTimePolicy {
  constructor(private readonly quiet: QuietHours) {}

  sendAt(dueAt: LocalDateTime, leadMinutes: number): LocalDateTime {
    const nominal = addMinutes(dueAt, -leadMinutes);
    return floorToSlot(this.quiet.pullBack(nominal));
  }
}

function floorToSlot(t: LocalDateTime): LocalDateTime {
  const s = toEpochSeconds(t);
  return fromEpochSeconds(s - (s % PUSH_SLOT_SECONDS));
}

